insert into public.pms_qa_checklist (item_id, template_id, section, sort, text, details, automation, automation_hint) values
('qa-001','deliverable-qa','General Document Verification',10,'Verify the project name, address, block/lot, client name, and project number match exactly on:','["Cover sheet","Title blocks","Specifications","Narratives","Calculations","Reports"]'::jsonb,'auto','search_drawings for the project name/number/address strings; extract_sheet_index + title-block fields from the drawing index'),
