('qa-003','deliverable-qa','General Document Verification',30,'Verify all sheet numbers listed on the drawing index are included in the PDF set.',null,'auto','extract_sheet_index (drawing list) vs sheets actually indexed in the set'),
('qa-004','deliverable-qa','General Document Verification',40,'Verify no sheets are duplicated, skipped, or mislabeled.',null,'auto','sheet_no list from the drawing index: duplicates, gaps, mislabels'),
('qa-005','deliverable-qa','General Document Verification',50,'Verify north arrows point in the same direction on all floor plans.',null,'assisted',null),
('qa-006','deliverable-qa','General Document Verification',60,'Verify floor plans from all disciplines use the same orientation and architectural background.',null,'manual',null),
('qa-007','deliverable-qa','General Document Verification',70,'Verify all plans, sections, details, and elevations include drawing scales.',null,'assisted',null),
('qa-008','deliverable-qa','General Document Verification',80,'Verify all required narratives, specifications, calculations, reports, and supporting documents are included in the submission package.',null,'assisted',null),
('qa-009','deliverable-qa','General Document Verification',90,'Verify all calculations are signed, dated, and saved in the project folder.',null,'manual',null),
