('qa-020','deliverable-qa','Drawing Graphics & Presentation',120,'Review plotted PDF at full size and half size. Verify all text remains readable at half size.','["Recommended minimum plotted text heights:","Sheet titles: 3/16\"","Major notes: 1/8\"","General notes/dimensions: 3/32\" minimum"]'::jsonb,'assisted',null),
('qa-021','deliverable-qa','Drawing Graphics & Presentation',130,'Verify text does not overlap:','["Walls","Ductwork","Piping","Conduit","Equipment","Other text"]'::jsonb,'assisted',null),
('qa-022','deliverable-qa','Drawing Graphics & Presentation',140,'Verify notes and dimensions do not extend outside sheet borders.',null,'assisted',null),
