('qa-024','deliverable-qa','Drawing Graphics & Presentation',160,'Verify hidden lines, centerlines, and demolition graphics are visually distinguishable.',null,'manual',null),
('qa-025','deliverable-qa','Drawing Graphics & Presentation',170,'Verify all detail callouts reference the correct detail and sheet number.',null,'assisted',null),
