('qa-029','deliverable-qa','Drawing Graphics & Presentation',210,'Verify legends and abbreviations include all symbols used on the drawings.',null,'assisted',null),
('qa-030','deliverable-qa','Drawing Graphics & Presentation',220,'Verify keynote numbering is sequential and no keynote references are missing.',null,'assisted',null),
('qa-031','deliverable-qa','Drawing Graphics & Presentation',230,'Verify no stray drafting lines, duplicate notes, empty text boxes, visible construction geometry, or CAD artifacts remain.',null,'manual',null),
('qa-032','deliverable-qa','Drawing Graphics & Presentation',240,'Search drawings/specifications for unresolved placeholders and verify they are removed or clarified:','["TBD","VERIFY","NIC","XXX","Lorem Ipsum","By Others","Insert Here"]'::jsonb,'auto','search_drawings for TBD / VERIFY / XXX / ''By Others'' / ''Insert Here'' / Lorem'),
('qa-033','deliverable-qa','Drawing Graphics & Presentation',250,'Verify all sheets plot correctly without:','["Missing xrefs","Shifted backgrounds","Corrupt graphics","Blank viewports","Missing raster images"]'::jsonb,'manual',null),
('qa-034','deliverable-qa','Drawing Graphics & Presentation',260,'Verify title blocks are complete and consistent on all sheets.',null,'assisted',null),
('qa-040','deliverable-qa','Room Names / Architectural Coordination',270,'Verify room names and room numbers match architectural drawings exactly.',null,'assisted',null),
