('qa-042','deliverable-qa','Room Names / Architectural Coordination',290,'Verify MEPFP equipment is not located in architecturally inappropriate spaces unless intentional.','["Examples:","No electrical panels in toilet rooms","No access panels centered in decorative ceilings","No exposed piping in finished feature spaces unless intentional"]'::jsonb,'assisted',null),
('qa-050','deliverable-qa','Equipment Coordination',300,'Compare MEPFP plans and verify major equipment appears in the same location on all disciplines.',null,'assisted',null),
('qa-051','deliverable-qa','Equipment Coordination',310,'Verify equipment shown on one discipline has corresponding utility connections shown on other disciplines.','["Examples:","HVAC equipment → power + condensate + controls","Pumps → power + drains + controls","Water heaters → power/gas + venting + drains","Fire pump → power + fire alarm + drains"]'::jsonb,'assisted',null),
('qa-052','deliverable-qa','Equipment Coordination',320,'Verify equipment tags match exactly between:','["Plans","Schedules","Details","Specifications","Control diagrams"]'::jsonb,'auto','find_equipment tag mode per tag: plans/schedules/details presence; read_drawing_schedule for the schedule side'),
