('qa-055','deliverable-qa','Equipment Coordination',350,'Verify manufacturer names and basis-of-design information are coordinated throughout the documents.',null,'assisted',null),
('qa-060','deliverable-qa','Electrical Voltage / Power Coordination',360,'Verify electrical characteristics for equipment are coordinated between mechanical/plumbing schedules and electrical drawings.','["Locate equipment on the mechanical/plumbing schedule.","Identify: Voltage, Phase, MCA, MOP/MOCP","Locate the same equipment on electrical drawings and panel schedules.","Verify voltages match exactly (480V → 480V panel, 208V → 120/208V panel, no 120V → 480V).","Verify phases match: single-phase → single-phase breaker, three-phase → 3-pole breaker.","Verify no equipment appears on mechanical/plumbing schedules without electrical connection shown.","Verify no electrical connections exist for equipment no longer shown."]'::jsonb,'auto','read_drawing_schedule on M/P schedules (V/Ph/MCA/MOCP columns) vs the same tags on E sheets and panel schedules'),
('qa-061','deliverable-qa','Electrical Voltage / Power Coordination',370,'Verify disconnect switches are shown where required for major mechanical equipment.',null,'assisted',null),
