-- QA Deliverables Checklist as CONTENT (was code-defined in SettyPMS.html's
-- CHECKLIST_TEMPLATES). One row per item; the seed mirrors the app template
-- verbatim, so item_ids stay stable and per-project check-off state in
-- project.checklists keeps working. `automation` says what the coordination
-- review can do with each item TODAY:
--   auto     - the connector checks it mechanically (drawing index, schedule
--              reader, tag registry, text search); automation_hint names how
--   assisted - Claude gathers evidence (text hits, rendered regions) and
--              flags exceptions; a human confirms
--   manual   - engineering/plot judgment, human only
-- `source` tracks provenance: 'seed' now; 'lesson' rows are added over time
-- from lessons learned, which is how the review gets smarter without a
-- deploy. Read for all authenticated (the app and the connector serve it);
-- writes admin-only, same posture as pms_capability_catalog / pms_regions.

create table if not exists public.pms_qa_checklist (
  item_id         text primary key,
  template_id     text not null default 'deliverable-qa',
  section         text not null,
  sort            int  not null default 0,
  text            text not null,
  details         jsonb,
  automation      text not null default 'assisted' check (automation in ('auto','assisted','manual')),
  automation_hint text,
  enabled         boolean not null default true,
  source          text not null default 'seed',
  added_by        text,
  added_at        timestamptz not null default now()
);

alter table public.pms_qa_checklist enable row level security;
drop policy if exists qa_checklist_read on public.pms_qa_checklist;
create policy qa_checklist_read on public.pms_qa_checklist for select to authenticated using (true);
drop policy if exists qa_checklist_admin_all on public.pms_qa_checklist;
create policy qa_checklist_admin_all on public.pms_qa_checklist for all
  using (is_pms_admin()) with check (is_pms_admin());
on conflict (item_id) do nothing;
